(OUT / 'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" fill="#243d36"/><text x="10" y="47" fill="#f2f0e9" font-family="Arial" font-size="43" font-weight="bold">M</text></svg>')
